import React, { useState, useEffect, useRef } from 'react';

interface EditableCellProps {
  value: any;
  onSave: (val: any) => void;
  type?: 'text' | 'number' | 'date';
  prefix?: string;
  className?: string;
}

const EditableCell: React.FC<EditableCellProps> = ({ 
  value, 
  onSave, 
  type = 'text', 
  prefix = '', 
  className = '' 
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [localValue, setLocalValue] = useState(value);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setLocalValue(value);
  }, [value]);

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    if (localValue !== value) {
      onSave(type === 'number' ? Number(localValue) : localValue);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleBlur();
    }
    if (e.key === 'Escape') {
      setLocalValue(value);
      setIsEditing(false);
    }
  };

  if (isEditing) {
    return (
      <input
        ref={inputRef}
        type={type}
        value={localValue}
        onChange={(e) => setLocalValue(e.target.value)}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        className={`w-full p-1 border-2 border-blue-400 outline-none rounded bg-white ${className}`}
      />
    );
  }

  return (
    <div 
      onClick={() => setIsEditing(true)}
      className={`p-2 cursor-pointer hover:bg-slate-50 rounded transition-colors min-h-[36px] flex items-center ${className}`}
    >
      {prefix}{value}
    </div>
  );
};

export default EditableCell;

import React from 'react';
import { GrosStatus, ExternStatus } from '../types';

interface StatusBadgeProps {
  status: string;
}

const statusConfig: Record<string, { label: string; color: string }> = {
  [GrosStatus.EN_PRODUCTION]: { label: 'En Production', color: 'bg-yellow-100 text-yellow-700' },
  [GrosStatus.EN_LIVRAISON]: { label: 'En Livraison', color: 'bg-blue-100 text-blue-700' },
  [GrosStatus.LIVREE_NON_ENCAISSE]: { label: 'Livré (Non Encaissé)', color: 'bg-purple-100 text-purple-700' },
  [GrosStatus.LIVREE_ENCAISSE]: { label: 'Livré (Encaissé)', color: 'bg-emerald-100 text-emerald-700' },
  [GrosStatus.RETOUR]: { label: 'Retour', color: 'bg-red-100 text-red-700' },
  [ExternStatus.LIVREE]: { label: 'Livré', color: 'bg-emerald-100 text-emerald-700' },
};

const StatusBadge: React.FC<StatusBadgeProps> = ({ status }) => {
  const config = statusConfig[status] || { label: status, color: 'bg-slate-100 text-slate-700' };

  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${config.color}`}>
      {config.label}
    </span>
  );
};

export default StatusBadge;

